+  await page
+    .locator(".gramaire__prose-editor")
+    .fill("# An h2\n\nBody text.\n\n## An h3\n\n### An h4\n");
+  await page.locator(".gramaire__statusbar").click();
+
+  await viewToggleButton(page, "Paper").click();
+  await expect(page.locator(".gramaire__paper")).toBeVisible();
+
+  const fontSize = (locator: import("@playwright/test").Locator) =>
+    locator.evaluate((el) => getComputedStyle(el).fontSize);
+
+  await expect(
+    fontSize(page.locator(".gramaire__paper h2").first()),
