+
+  const fontSize = (locator: import("@playwright/test").Locator) =>
+    locator.evaluate((el) => getComputedStyle(el).fontSize);
+
+  // Notebook's own compact scale is a flat, unscaled 21px — the directive never reaches it.
+  await expect(
+    fontSize(page.locator(".gramaire__prose h2").first()),
+  ).resolves.toBe("21px");
+
+  await viewToggleButton(page, "Paper").click();
+  await expect(page.locator(".gramaire__paper")).toBeVisible();
+  await expect(
+    fontSize(page.locator(".gramaire__paper h2").first()),
+  ).resolves.toBe(
+    "48px", // 24px base * 2
+  );
+  await expect(
+    fontSize(page.locator(".gramaire__paper p").first()),
+  ).resolves.toBe(
+    "34px", // 17px base * 2
+  );
+});
